import{_ as e,c as r,o as i,a4 as t}from"./chunks/framework.3gYJpwF9.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),o={name:"guide/introduction.md"};function l(n,a,s,h,d,u){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>Apron Design Vue 是一个基于 Vue 3 的现代化组件库，使用 TypeScript 和 SCSS 构建，提供 40+ 高质量组件。</p><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>🎨 <strong>精心设计</strong> - 基于现代设计理念，提供简洁优雅的视觉体验</li><li>🌙 <strong>暗黑模式</strong> - 内置完整的暗黑模式支持</li><li>📦 <strong>丰富组件</strong> - 40+ 组件覆盖各种业务场景</li><li>🔧 <strong>TypeScript</strong> - 完整的类型定义</li><li>🎯 <strong>按需引入</strong> - 支持 Tree Shaking</li><li>⚡ <strong>高性能</strong> - 基于 Vue 3 Composition API</li></ul><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to &quot;设计理念&quot;">​</a></h2><h3 id="简洁" tabindex="-1">简洁 <a class="header-anchor" href="#简洁" aria-label="Permalink to &quot;简洁&quot;">​</a></h3><p>我们相信简洁的设计能够帮助用户更好地聚焦于内容本身。Apron Design 的每个组件都经过精心设计，去除冗余的装饰，保留核心功能。</p><h3 id="一致性" tabindex="-1">一致性 <a class="header-anchor" href="#一致性" aria-label="Permalink to &quot;一致性&quot;">​</a></h3><p>组件库遵循统一的设计语言和交互模式，确保用户在不同组件间切换时能够获得一致的体验。</p><h3 id="可定制" tabindex="-1">可定制 <a class="header-anchor" href="#可定制" aria-label="Permalink to &quot;可定制&quot;">​</a></h3><p>通过 CSS 变量（Custom Properties），你可以轻松自定义组件的外观，以适应不同的品牌需求。</p><h2 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h2><ul><li>Vue 3.3+</li><li>现代浏览器（Chrome、Firefox、Safari、Edge）</li><li>支持 SSR</li></ul><h2 id="贡献" tabindex="-1">贡献 <a class="header-anchor" href="#贡献" aria-label="Permalink to &quot;贡献&quot;">​</a></h2><p>欢迎参与贡献！你可以通过以下方式参与：</p><ul><li>提交 Issue 报告问题</li><li>提交 Pull Request 改进代码</li><li>完善文档</li><li>分享使用经验</li></ul><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p><a href="https://opensource.org/licenses/MIT" target="_blank" rel="noreferrer">MIT License</a></p>',18)])])}const g=e(o,[["render",l]]);export{p as __pageData,g as default};
